using UnityEngine;
using UnityEngine.InputSystem;
namespace CarTest { public sealed class CarController : MonoBehaviour { [SerializeField] float acceleration=22, reverseAcceleration=13, maxSpeed=31, steering=86, drag=7, brake=25; float speed; Rigidbody body; Vector3 startPosition; Quaternion startRotation; public float SpeedKph=>Mathf.Abs(speed)*3.6f; public float Progress=>Mathf.Clamp01((transform.position.z+27f)/59f)*100f; void Awake(){body=gameObject.AddComponent<Rigidbody>();body.isKinematic=true;body.useGravity=false;body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;startPosition=transform.position;startRotation=transform.rotation;} void Update(){var kb=Keyboard.current;float throttle=0,turn=0;if(kb!=null){if(kb.wKey.isPressed||kb.upArrowKey.isPressed)throttle=1;if(kb.sKey.isPressed||kb.downArrowKey.isPressed)throttle=-1;if(kb.aKey.isPressed||kb.leftArrowKey.isPressed)turn=-1;if(kb.dKey.isPressed||kb.rightArrowKey.isPressed)turn=1;if(kb.rKey.wasPressedThisFrame)ResetCar();}if(Mathf.Abs(throttle)>.01f)speed+=throttle*(throttle>0?acceleration:reverseAcceleration)*Time.deltaTime;else speed=Mathf.MoveTowards(speed,0,(kb!=null&&kb.spaceKey.isPressed?brake:drag)*Time.deltaTime);speed=Mathf.Clamp(speed,-maxSpeed*.42f,maxSpeed);float direction=speed<-.1f?-1:1;transform.Rotate(0,turn*steering*Mathf.Clamp01(Mathf.Abs(speed)/4f)*direction*Time.deltaTime,0,Space.World);Vector3 next=transform.position+transform.forward*(speed*Time.deltaTime);next.x=Mathf.Clamp(next.x,-5.25f,5.25f);next.y=startPosition.y;if(next.z>34){next.z=34;speed=0;}if(next.z< -32){next.z= -32;speed=0;}body.MovePosition(next);}void ResetCar(){speed=0;body.position=startPosition;body.rotation=startRotation;transform.SetPositionAndRotation(startPosition,startRotation);} } }